    'Směr nejde spolehlivě určit: typický měsíc {typical}, ale průměr by ukázal {mean}. Výsledek otáčí jeden mimořádný měsíc ({spike}), typicky kampaň nebo výpadek.' => 'Smer sa nedá spoľahlivo určiť: typický mesiac {typical}, ale priemer by ukázal {mean}. Výsledok otáča jeden mimoriadny mesiac ({spike}), typicky kampaň alebo výpadok.',
    'Změna typického měsíce je do ±10 %, proto „stabilní".' => 'Zmena typického mesiaca je do ±10 %, preto „stabilné“.',
    'stabilní {value}' => 'stabilné {value}',
    'Meziročně: typický měsíc {label} (stejná sezóna), přepočteno na den s daty.' => 'Medziročne: typický mesiac {label} (rovnaká sezóna), prepočítané na deň s dátami.',
    'Směr nejde spolehlivě určit: typický měsíc {typical}, průměr {mean}, výkyv {spike}.' => 'Smer sa nedá spoľahlivo určiť: typický mesiac {typical}, priemer {mean}, výkyv {spike}.',
